-- Uncle Nearest import (bourbon.uncle_nearest), applied 2026-09-24 via the Supabase MCP. No hand steps.
-- The site's alt-text/filename bottle images vary page to page (a themed 'bottle-*.png', an upload with alt='Bottle of ...', or a filename with no bottle marker); the parser tries the filename first, the alt text second.
-- 1820 and the Single Barrel Black Label (Barrel 007) pick stay untouched (STALE): the current nav doesn't cover them and it's not clear whether they're retired or still sold through retailers.

update cellar.products set image_url = coalesce(image_url, 'https://unclenearest.com/wp-content/uploads/2022/12/UN_MBE_bottle.png'), producer = coalesce(producer, 'Uncle Nearest'), producer_id = coalesce(producer_id, 'e1eb2d6d-97d7-4a36-88cb-a6da57af8e74'::uuid), source_url = 'https://unclenearest.com/master-blend/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '0619843d-df17-4481-82d2-7e81c80f39c9' and facts_verified_at is null;
update cellar.products set image_url = coalesce(image_url, 'https://unclenearest.com/wp-content/uploads/2022/12/bottle-single.png'), producer = coalesce(producer, 'Uncle Nearest'), producer_id = coalesce(producer_id, 'e1eb2d6d-97d7-4a36-88cb-a6da57af8e74'::uuid), source_url = 'https://unclenearest.com/single-barrel-whiskey/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '0f1f5e66-e908-4307-be34-618814302df7' and facts_verified_at is null;
update cellar.products set image_url = coalesce(image_url, 'https://unclenearest.com/wp-content/uploads/2022/11/bottle-straight-rye.png'), producer = coalesce(producer, 'Uncle Nearest'), producer_id = coalesce(producer_id, 'e1eb2d6d-97d7-4a36-88cb-a6da57af8e74'::uuid), source = 'maker', source_url = 'https://unclenearest.com/straight-rye-whiskey/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '24a85f7f-7fa4-48c6-8c65-dcc57036bb38' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('9dcb78fc-36d8-4962-85ef-2d0ab9674b38', '456f14ce-54d6-4fcd-a1ee-d936850add8c', '93d33d42-dcad-4f8d-a1f2-5429aa40a9c9', '0619843d-df17-4481-82d2-7e81c80f39c9', '0f1f5e66-e908-4307-be34-618814302df7', '24a85f7f-7fa4-48c6-8c65-dcc57036bb38');
update cellar.products set source = 'maker', source_url = 'https://unclenearest.com/1884-small-batch-whiskey/', discontinued = false, catalog_included = catalog_included or is_core_range, producer = coalesce(producer, 'Uncle Nearest'), producer_id = coalesce(producer_id, 'e1eb2d6d-97d7-4a36-88cb-a6da57af8e74'::uuid), image_url = coalesce(image_url, 'https://unclenearest.com/wp-content/themes/unclenearest/lib/img/bottle-1884-lft.png') where id = '9dcb78fc-36d8-4962-85ef-2d0ab9674b38' and facts_verified_at is null;
update cellar.products set source = 'maker', source_url = 'https://unclenearest.com/premium-aged-whiskey/', discontinued = false, catalog_included = catalog_included or is_core_range, producer = coalesce(producer, 'Uncle Nearest'), producer_id = coalesce(producer_id, 'e1eb2d6d-97d7-4a36-88cb-a6da57af8e74'::uuid), image_url = coalesce(image_url, 'https://unclenearest.com/wp-content/themes/unclenearest/lib/img/bottle-1856.png') where id = '456f14ce-54d6-4fcd-a1ee-d936850add8c' and facts_verified_at is null;
update cellar.products set source_url = 'https://unclenearest.com/uncut-unfiltered-straight-rye-whiskey/', discontinued = false, catalog_included = catalog_included or is_core_range, producer = coalesce(producer, 'Uncle Nearest'), producer_id = coalesce(producer_id, 'e1eb2d6d-97d7-4a36-88cb-a6da57af8e74'::uuid) where id = '93d33d42-dcad-4f8d-a1f2-5429aa40a9c9' and facts_verified_at is null;
insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://unclenearest.com/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', '{}'::jsonb, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), r.img, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Uncle Nearest Nearest Green","rar":"shelf","f":"Uncle Nearest","x":"Nearest Green","p":84.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"tennessee","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://unclenearest.com/wp-content/uploads/2024/09/pro_image_tr.png","u":"https://unclenearest.com/nearest-green-tennessee-whiskey/","pr":"Uncle Nearest","mk":"e1eb2d6d-97d7-4a36-88cb-a6da57af8e74"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');